INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(4701, 'Deuteronomy 7:15', 'Deuteronomy', 7, 15, '&nbsp;مالِک خُدائ به تاسو د ټولو بيمارو نه وساتى، هغه به په تاسو باندې داسې خرابې بيمارۍ نۀ راولى کومې چې تاسو په مِصر کښې ليدلې وې، خو هغه بيمارۍ به ستاسو په ټولو دشمنانو راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4702, 'Deuteronomy 7:16', 'Deuteronomy', 7, 16, '&nbsp;هغه هر يو قوم تباه کړئ په کوم چې مالِک خُدائ ستاسو خُدائ پاک تاسو زورَور کړى يئ او چې په هغوئ باندې هيڅ رحم ونۀ کړئ. د هغوئ د معبودانو عبادت مۀ کوئ، ځکه چې دا به ستاسو دپاره يو دام جوړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4703, 'Deuteronomy 7:17', 'Deuteronomy', 7, 17, '&nbsp;په خپل زړۀ کښې دا مۀ وايئ چې دا قومونه ستاسو نه په شمېر کښې زيات دى او هغوئ تاسو نۀ شئ شړلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4704, 'Deuteronomy 7:18', 'Deuteronomy', 7, 18, '&nbsp;د هغوئ نه مۀ يرېږئ، هغه څۀ راپه ياد کړئ چې مالِک خُدائ ستاسو خُدائ پاک په فِرعون او په ټول مِصر وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4705, 'Deuteronomy 7:19', 'Deuteronomy', 7, 19, '&nbsp;هغه سختې وباګانې، معجزې او نښې رايادې کړئ چې تاسو په خپلو سترګو وليدلې او هغه لوئ طاقت او قوت چې د کوم په ذريعه مالِک خُدائ ستاسو خُدائ پاک تاسو آزاد کړئ. لکه څنګه چې هغۀ مِصريان تباه کړل، نو هغه ټول خلق به هم هغه شان تباه کړى چې تاسو ترې نه يرېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4706, 'Deuteronomy 7:20', 'Deuteronomy', 7, 20, '&nbsp;هغه به په هغوئ وارخطائى ورولېږى او هغه به هغوئ هم تباه کړى چې څوک تښتى او پټيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4707, 'Deuteronomy 7:21', 'Deuteronomy', 7, 21, '&nbsp;نو د دې خلقو نه مۀ يرېږئ. مالِک خُدائ ستاسو خُدائ پاک ستاسو مل دے، خُدائ پاک لوئ او يروونکے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4708, 'Deuteronomy 7:22', 'Deuteronomy', 7, 22, '&nbsp;چې تاسو مخ په وړاندې ځئ نو هغه به دا قومونه لږ لږ شړى. تاسو به هغوئ ټول په يو ځل نۀ شئ شړلے، ځکه کۀ تاسو داسې وکړل، نو ځنګلى ځناور به زيات شى او دا به ستاسو دپاره يوه خطره جوړه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4709, 'Deuteronomy 7:23', 'Deuteronomy', 7, 23, '&nbsp;مالِک خُدائ به تاسو ستاسو په دشمنانو زورَور کړى او تر هغې پورې به وارخطا وى چې ترڅو تباه شوى نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4710, 'Deuteronomy 7:24', 'Deuteronomy', 7, 24, '&nbsp;هغه به د هغوئ په بادشاهانو تاسو زورَور کړى. تاسو به هغوئ ووژنئ او هغوئ به هېر کړے شى. هيڅ څوک به ستاسو مخه نۀ شى نيولے، تاسو به هر يو تباه کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4711, 'Deuteronomy 7:25', 'Deuteronomy', 7, 25, '&nbsp;د هغوئ بُتان وسوزوئ. په دې باندې چې کوم سپين زر يا سرۀ زر لګېدلى وى، د هغې خواهش مۀ کوئ، هغه ترې نه د خپلو ځانونو دپاره مۀ اخلئ. ګنې دا به ستاسو دپاره يو دام جوړ شى، ځکه چې مالِک خُدائ ستاسو خُدائ پاک د بُت پرستۍ نه نفرت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4712, 'Deuteronomy 7:26', 'Deuteronomy', 7, 26, '&nbsp;هغه بُتان خپلو کورونو ته مۀ راوړئ، ګنې په تاسو به هم هغه لعنت وى کوم چې په هغوئ دے. تاسو خامخا د دې بُتانو نه کرکه کوئ او سپک ورته ګورئ، ځکه چې دا لعنتى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4713, 'Deuteronomy 8:1', 'Deuteronomy', 8, 1, '&nbsp;ما چې نن کوم قانون درکړے دے په هغه ټول په وفادارۍ سره عمل کوئ، نو چې داسې تاسو ژوندى پاتې شئ او ودان شئ او هغه مُلک قبضه کړئ چې مالِک خُدائ د هغې وعده ستاسو پلار نيکۀ سره کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4714, 'Deuteronomy 8:2', 'Deuteronomy', 8, 2, '&nbsp;هغه راياد کړئ چې مالِک خُدائ ستاسو خُدائ پاک په تېرو څلوېښتو کالونو کښې څنګه په بيابان کښې په دې اوږد سفر کښې ستاسو لارښودنه وکړه، او په تاسو يې سختۍ راولېږلې چې په تاسو کښې عاجزى وى او تاسو وآزمائى، نو چې هغه په دې پوهه شى چې ستاسو په زړۀ کښې څۀ دى نو چې د هغۀ په حُکمونو عمل کوئ او کۀ نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4715, 'Deuteronomy 8:3', 'Deuteronomy', 8, 3, '&nbsp;هغۀ په تاسو باندې عاجزى او لوږه راوستله، نو بيا هغۀ تاسو له د خوراک دپاره من درکړل، هغه خوراک چې د دې نه مخکښې هيڅکله ستاسو پلار نيکۀ هم نۀ وو خوړلے. هغۀ دا د دې دپاره وکړل چې تاسو ته وښائى چې بنى آدم دې په دې يقين نۀ ساتى چې هغه تش په روټۍ پائى، خو هغه په هره هغه خبره پائى چې د مالِک خُدائ د خولې نه راوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4716, 'Deuteronomy 8:4', 'Deuteronomy', 8, 4, '&nbsp;په دې څلوېښتو کالو کښې ستاسو جامې نۀ دى زَړې شوې او نۀ مو پښې پړسېدلې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4717, 'Deuteronomy 8:5', 'Deuteronomy', 8, 5, '&nbsp;ياد لرئ چې مالِک خُدائ ستاسو خُدائ پاک ستاسو د اصلاح دپاره سزا درکوى لکه چې يو پلار خپلو بچو له تربيت ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4718, 'Deuteronomy 8:6', 'Deuteronomy', 8, 6, '&nbsp;نو بيا، هم هغه شان کوئ چې څنګه مالِک خُدائ حُکم درکړے دے، د هغۀ د قانون په مطابق ژوند تېروئ او د هغۀ تابعدارى کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4719, 'Deuteronomy 8:7', 'Deuteronomy', 8, 7, '&nbsp;مالِک خُدائ ستاسو خُدائ پاک تاسو هغه زرخېز مُلک ته راولى، يو داسې مُلک چې سيندونه او ولې په کښې وى چې د هغه چينو نه وتلې وى چې د درو او غرونو نه بهيږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4720, 'Deuteronomy 8:8', 'Deuteronomy', 8, 8, '&nbsp;يو داسې مُلک چې غنم، اوربشې، انګور، اينځر، انار، د زيتُونو تېل او شات په کښې پېدا کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4721, 'Deuteronomy 8:9', 'Deuteronomy', 8, 9, '&nbsp;هلته به هيڅکله اوږى نۀ شئ او نۀ به محتاج شئ. د هغې په تيږو کښې اوسپنه شته دے او د هغې غرونو نه تاسو تانبه راويستلے شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4722, 'Deuteronomy 8:10', 'Deuteronomy', 8, 10, '&nbsp;تاسو چې د خوراک دپاره څۀ غواړئ هغه هر څۀ به درته ملاويږى او چې مالِک خُدائ ستاسو خُدائ پاک کوم آباد مُلک درکړے دے د هغې دپاره به تاسو د هغۀ شُکر ادا کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4723, 'Deuteronomy 8:11', 'Deuteronomy', 8, 11, '&nbsp;پام کوئ چې مالِک خُدائ ستاسو خُدائ پاک هېر نۀ کړئ، نن چې کوم قانون زۀ درکوم چې په هغې باندې عمل کولو کښې ناکامه نۀ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4724, 'Deuteronomy 8:12', 'Deuteronomy', 8, 12, '&nbsp;کله چې تاسو ته د خوراک دپاره هغه هر څۀ مِلاو شى چې تاسو يې غواړئ او د اوسېدو دپاره ښائسته کورونه جوړ کړئ', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4725, 'Deuteronomy 8:13', 'Deuteronomy', 8, 13, '&nbsp;کله چې ستاسو څاروى، ګډې، ستاسو سپين زر او سرۀ زر او ستاسو نور هر څيز زيات شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4726, 'Deuteronomy 8:14', 'Deuteronomy', 8, 14, '&nbsp;نو دا خبره يقينى کړئ چې تاسو مغروره نۀ شئ او مالِک خُدائ ستاسو خُدائ پاک هېر نۀ کړئ چې هغۀ تاسو د مِصر نه راوويستلئ، چرته چې تاسو غلامان وئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4727, 'Deuteronomy 8:15', 'Deuteronomy', 8, 15, '&nbsp;هغۀ تاسو د هغه لوئ او يروونکى بيابان په لاره بوتلئ چرته چې زهريله ماران او لړمان وُو. په هغه خُشکه او تږې زمکه کښې هغۀ ستاسو دپاره د سختې تيږې نه اوبۀ روانې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4728, 'Deuteronomy 8:16', 'Deuteronomy', 8, 16, '&nbsp;په بيابان کښې د خوراک دپاره هغۀ تاسو له من درکړل، هغه خوراک چې ستاسو پلار نيکۀ هيڅکله نۀ وو خوړلے. هغۀ په تاسو سختۍ راولېږلې چې تاسو وآزمائى، نو چې داسې په آخر کښې ستاسو هر څۀ سم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4729, 'Deuteronomy 8:17', 'Deuteronomy', 8, 17, '&nbsp;پام کوئ چې تاسو په خپل زړۀ کښې دا ونۀ وايئ چې په خپل طاقت او قوت سره تاسو خپل ځانونه مالداره کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4730, 'Deuteronomy 8:18', 'Deuteronomy', 8, 18, '&nbsp;ياد لرئ دا مالِک خُدائ ستاسو خُدائ پاک دے چې هغۀ تاسو له د مالداره کېدو طاقت درکړے دے. هغه ځکه دا کوى چې هغه تر نن ورځ پورې وفادار دے چې په هغه لوظ ودرېږى کوم چې هغۀ ستاسو پلار نيکۀ سره کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4731, 'Deuteronomy 8:19', 'Deuteronomy', 8, 19, '&nbsp;هيڅکله مالِک خُدائ ستاسو خُدائ پاک مۀ هېروئ او نۀ چې نورو معبودانو ته واوړئ چې د هغوئ عبادت او خِدمت وکړئ. کۀ تاسو داسې وکړل، نو زۀ نن تاسو له خبردارے درکوم چې بې‌شکه تاسو به تباه شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4732, 'Deuteronomy 8:20', 'Deuteronomy', 8, 20, '&nbsp;کۀ چرې تاسو د مالِک خُدائ تابعدارى ونۀ کړئ، نو د هغه قومونو په شان به تاسو تباه شئ کوم چې مالِک خُدائ ستاسو خُدائ پاک ستاسو مخ په وړاندې تلو سره تباه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4733, 'Deuteronomy 9:1', 'Deuteronomy', 9, 1, '&nbsp;اے بنى اِسرائيلو واورئ. تاسو به نن د اُردن سيند نه پورې وځئ او هغه مُلک به قبضه کړئ چې د هغه قومونو دے چې ستاسو نه لوئ او طاقتور دى. د هغوئ ښارونه لوئ لوئ دى چې دېوالونه يې آسمان ته رسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4734, 'Deuteronomy 9:2', 'Deuteronomy', 9, 2, '&nbsp;هغه خلق په خپله تکړه او لوړ لوړ دى، هغوئ دېوان دى او تاسو دا خبره اورېدلې ده چې د هغوئ په مقابله کښې هيڅ څوک نۀ شى ودرېدلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4735, 'Deuteronomy 9:3', 'Deuteronomy', 9, 3, '&nbsp;خو تاسو به په خپله وګورئ چې مالِک خُدائ ستاسو خُدائ پاک به د بل شوى اور په شان ستاسو نه مخکښې روان وى. چې مخ په وړاندې ځئ نو خُدائ پاک به هغوئ له شکست ورکړى، هغوئ به وشړئ او زر به يې تباه کړئ، هم هغه شان چې څنګه هغۀ وعده کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4736, 'Deuteronomy 9:4', 'Deuteronomy', 9, 4, '&nbsp;کله چې مالِک خُدائ ستاسو خُدائ پاک هغوئ ستاسو دپاره د هغه مُلک نه وباسى، نو په خپل زړۀ کښې داسې مۀ وايئ چې ګنې تاسو نېک خلق يئ او د دې دپاره يې راوستلئ چې دا مُلک ستاسو شى. داسې نۀ ده، مالِک خُدائ دا خلق ستاسو دپاره ځکه وباسى چې هغوئ بدکاره دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4737, 'Deuteronomy 9:5', 'Deuteronomy', 9, 5, '&nbsp;په دې وجه نۀ چې تاسو نېک عمله او ښۀ خلق يئ خو مالِک خُدائ تاسو پرېږدى چې د هغوئ مُلک ونيسئ. هغه به هغوئ وشړى ځکه چې هغوئ بدعمله خلق دى او د هغۀ اراده دا ده چې ستاسو پلار نيکۀ، اِبراهيم، اِسحاق، او يعقوب سره يې کومه وعده کړې وه هغه پوره کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4738, 'Deuteronomy 9:6', 'Deuteronomy', 9, 6, '&nbsp;ځان په دې ښۀ پوهه کړئ چې مالِک خُدائ دا زرخيزه مُلک تاسو له ستاسو د ښۀ‌والى په وجه نۀ درکوى بلکې تاسو خو ضدى خلق يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4739, 'Deuteronomy 9:7', 'Deuteronomy', 9, 7, '&nbsp;دا خبره مۀ هېروئ چې مالِک خُدائ ستاسو خُدائ پاک په بيابان کښې تاسو څنګه غصه کړو. د هغه ورځې نه واخله چې تاسو په کښې د مِصر نه راووتلئ تر ننه پورې چې دلته راورسېدلئ، تاسو د هغۀ خِلاف بغاوت کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4740, 'Deuteronomy 9:8', 'Deuteronomy', 9, 8, '&nbsp;د سينا په غرۀ باندې هم تاسو مالِک خُدائ دومره غصه کړو چې ستاسو بربادولو ته تيار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4741, 'Deuteronomy 9:9', 'Deuteronomy', 9, 9, '&nbsp;زۀ غرۀ ته وختلم چې د کاڼو هغه تختې راواخلم چې هغه لوظ ورباندې ليکلے شوے وو کوم چې مالِک خُدائ تاسو سره کړے دے. زۀ هلته بغېر د څۀ خوراک څښاک نه څلوېښت ورځې او څلوېښت شپې پاتې شوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4742, 'Deuteronomy 9:10', 'Deuteronomy', 9, 10, '&nbsp;بيا مالِک خُدائ ما له د کاڼو هغه دوه تختې راکړې چې په هغې باندې هغۀ په خپله هغه څۀ ليکلى وُو څۀ يې چې په هغه ورځ د اور نه تاسو ته فرمائيلى وُو چې هلته د غرۀ سره راغونډ وئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4743, 'Deuteronomy 9:11', 'Deuteronomy', 9, 11, '&nbsp;د هغه څلوېښتو ورځو او څلوېښتو شپو نه وروستو مالِک خُدائ ما له د کاڼو هغه دوه تختې راکړې چې په کومو باندې هغۀ شريعت ليکلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4744, 'Deuteronomy 9:12', 'Deuteronomy', 9, 12, '&nbsp;بيا مالِک خُدائ ما ته وفرمائيل چې سمدستى د غرۀ نه کوز شه، ځکه چې ستا خلق کوم چې تا د مِصر نه راوويستل، هغوئ مرتد شوى دى. هغوئ د هغه څۀ نه زر اوړېدلى دى چې ما يې حُکم ورکړے دے او هغوئ د خپلو ځانونو دپاره د سرو زرو يو بُت جوړ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4745, 'Deuteronomy 9:13', 'Deuteronomy', 9, 13, '&nbsp;مالِک خُدائ ما ته دا هم وفرمائيل، ما ته پته ده چې دا څومره ضدى خلق دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4746, 'Deuteronomy 9:14', 'Deuteronomy', 9, 14, '&nbsp;تۀ د هغوئ دپاره ما ته مِنت ونۀ کړې. زۀ هغوئ تباه کوم او هيڅ څوک به يې بيا نوم وانۀ خلى. نو زۀ به تا د داسې قوم پلار جوړ کړم چې د دوئ نه به لوئ او طاقتور وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4747, 'Deuteronomy 9:15', 'Deuteronomy', 9, 15, '&nbsp;نو زۀ واپس شوم او د غرۀ نه راکوز شوم، هغه د کاڼو دوه تختې مې راروانې کړې وې چې په کومو باندې شريعت ليکلے شوے وو. د غر نه د اور لمبې ختلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4748, 'Deuteronomy 9:16', 'Deuteronomy', 9, 16, '&nbsp;ما ته پته ولګېده چې تاسو د هغه حُکم نافرمانى کړې ده کوم چې مالِک خُدائ ستاسو خُدائ پاک تاسو له درکړے وو او تاسو د هغۀ خِلاف ګناه کړې وه چې د سخى په شکل کښې مو د سرو زرو بُت جوړ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4749, 'Deuteronomy 9:17', 'Deuteronomy', 9, 17, '&nbsp;نو هلته ستاسو په مخکښې ما د کاڼو تختې راوغورزولې او ټوټې ټوټې مې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4750, 'Deuteronomy 9:18', 'Deuteronomy', 9, 18, '&nbsp;نو يو ځل بيا زۀ د مالِک خُدائ په حضور کښې څلوېښت ورځې او څلوېښت شپې پړمخې پرېوتم او نۀ مې څۀ خوړل او نۀ مې څۀ څښل. دا ځکه چې تاسو د مالِک خُدائ خِلاف ګناه کړې وه او هغه مو غصه کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4751, 'Deuteronomy 9:19', 'Deuteronomy', 9, 19, '&nbsp;زۀ د مالِک خُدائ د سخت قهر نه ويرېدم، ځکه چې هغه دومره غصه وو چې تاسو تباه کړى، خو مالِک خُدائ يو ځل بيا زما واورېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4752, 'Deuteronomy 9:20', 'Deuteronomy', 9, 20, '&nbsp;مالِک خُدائ هارون ته هم دومره غصه وو چې وې وژنى، نو په هغه وخت ما د هارون دپاره هم دُعا وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4753, 'Deuteronomy 9:21', 'Deuteronomy', 9, 21, '&nbsp;ما هغه د ګناه نه ډک څيز يعنې د سرو زرو سخے واخستو کوم چې تاسو جوړ کړے وو او په اور کښې مې واچولو. بيا ما دا ټوټې ټوټې کړو، د اوړو په شان مې مېده کړو او هغه مې په هغه وَله کښې وغورزولو چې د غر نه لاندې بهېده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4754, 'Deuteronomy 9:22', 'Deuteronomy', 9, 22, '&nbsp;کله چې تاسو په تبيعره، مسه، قبروت هتاوه کښې وئ نو تاسو هلته هم مالِک خُدائ غصه کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4755, 'Deuteronomy 9:23', 'Deuteronomy', 9, 23, '&nbsp;او چې کله هغۀ تاسو د قادِس برنيع نه د دې حُکمونو سره ولېږلئ چې لاړ شئ او هغه مُلک ونيسئ کوم يې چې تاسو له درکولو، نو تاسو د هغۀ خِلاف سرکشى وکړه، تاسو په هغۀ يقين ونۀ کړو او نۀ مو د هغۀ فرمانبردارى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4756, 'Deuteronomy 9:24', 'Deuteronomy', 9, 24, '&nbsp;چې د کوم وخت نه ما تاسو پېژندلى يئ، تاسو د مالِک خُدائ خِلاف سرکشى کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4757, 'Deuteronomy 9:25', 'Deuteronomy', 9, 25, '&nbsp;نو په هغه څلوېښتو ورځو او څلوېښتو شپو کښې زۀ د مالِک خُدائ په حضور کښې پړمخې پروت وم، دا ځکه چې ما ته پته وه چې هغه ستاسو د تباه کولو اراده لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4758, 'Deuteronomy 9:26', 'Deuteronomy', 9, 26, '&nbsp;او ما دُعا وکړه، اے مالِکه خُدايه، خپل خلق مۀ تباه کوه، هغه خلق چې تا بچ کړل او د خپل لوئ طاقت او قوت سره دې د مِصر نه راوويستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4759, 'Deuteronomy 9:27', 'Deuteronomy', 9, 27, '&nbsp;خپل خِدمت کوونکے اِبراهيم، اِسحاق او يعقوب راياد کړه او د دې خلقو ضد، بدکارۍ او ګناه ته مۀ ګوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4760, 'Deuteronomy 9:28', 'Deuteronomy', 9, 28, '&nbsp;ګنې، مِصريان به ووائى چې تۀ د دې جوګه نۀ يې چې خپل خلق هغه مُلک ته بوځې چې د هغوئ سره دې وعده کړې ده. هغوئ به ووائى چې تا خپل خلق بيابان ته د دې دپاره بوتلل چې هغوئ ووژنې، ځکه چې تا د هغوئ نه نفرت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4761, 'Deuteronomy 9:29', 'Deuteronomy', 9, 29, '&nbsp;د دې هر څۀ نه علاوه، دا هغه خلق دى چې تا خوښ کړل چې ستا خپل خلق شى او د خپل لوئ طاقت او قوت سره دې هغوئ د مِصر نه راوويستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4762, 'Deuteronomy 10:1', 'Deuteronomy', 10, 1, '&nbsp;په هغه وخت کښې مالِک خُدائ ما ته وفرمائيل، ”د اولنو په شان دوه د کاڼى تختې جوړې کړه او يو د لرګى صندوق جوړ کړه چې هغه تختې په کښې کېږدې. په غر باندې ما ته راوخېژه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4763, 'Deuteronomy 10:2', 'Deuteronomy', 10, 2, '&nbsp;او زۀ به په هغې باندې هم هغه څۀ وليکم څۀ چې ما په هغه تختو باندې ليکلى وُو چې تا ماتې کړې او بيا به تۀ هغه په صندوق کښې کېږدې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4764, 'Deuteronomy 10:3', 'Deuteronomy', 10, 3, '&nbsp;نو ما د کيکر لرګى نه يو صندوق جوړ کړو او د اولنو په شان مې د کاڼى دوه تختې جوړې کړې او د ځان سره مې غر ته وخېژولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4765, 'Deuteronomy 10:4', 'Deuteronomy', 10, 4, '&nbsp;بيا مالِک خُدائ په هغه تختو باندې هم هغه خبرې وليکلې کومې چې هغۀ په وړومبى ځل ليکلې وې، دا هغه لس حُکمونه وُو چې تاسو له يې په هغه ورځ درکړل چې د غر سره راغونډ وئ او هغۀ د اور نه خبرې وکړې. مالِک خُدائ ما له تختې راکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4766, 'Deuteronomy 10:5', 'Deuteronomy', 10, 5, '&nbsp;او زۀ د غرۀ نه راکوز شوم څنګه چې مالِک خُدائ ما ته حُکم کړے وو، نو تختې مې په صندوق کښې کېښودلې. او هغه تختې تر اوسه پورې په صندوق کښې پرتې دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4767, 'Deuteronomy 10:6', 'Deuteronomy', 10, 6, '&nbsp;بنى اِسرائيل د يعقان د خلقو د کُوهو نه روان شول او موسيره ته لاړل. او هلته هارون په حق ورسېدو او دفن شو او د هغۀ زوئ اِلى‌عزر د هغۀ په ځائ د اِمام په توګه خِدمت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4768, 'Deuteronomy 10:7', 'Deuteronomy', 10, 7, '&nbsp;د هغه ځائ نه هغوئ جدجوده او بيا يُطباته ته لاړل، هغه مُلک چې د اوبو ډېر نِهرونه په کښې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4769, 'Deuteronomy 10:8', 'Deuteronomy', 10, 8, '&nbsp;په هغه وخت مالِک خُدائ د ليوى قبيلې سړى مقرر کړل چې د لوظ صندوق وړى او د اِمامانو په توګه د هغۀ خِدمت کوى او د هغۀ په نوم برکت غواړى. او تر اوسه پورې د هغوئ دا ذمه وارۍ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4770, 'Deuteronomy 10:9', 'Deuteronomy', 10, 9, '&nbsp;نو د ليوى قبيلې ته د نورو قبيلو په شان زمکه مِلاو نۀ شوه، مالِک خُدائ په خپله د هغوئ ميراث وو هم هغه شان چې څنګه مالِک خُدائ ستاسو خُدائ پاک وعده کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4771, 'Deuteronomy 10:10', 'Deuteronomy', 10, 10, '&nbsp;”د وړومبى ځل په شان زۀ په غر باندې څلوېښت ورځې او څلوېښت شپې ايسار شوم، مالِک خُدائ يو ځل بيا زما خبرې ته غوږ ونيولو او په دې رضا شو چې تاسو به نۀ تباه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4772, 'Deuteronomy 10:11', 'Deuteronomy', 10, 11, '&nbsp;بيا هغۀ ما ته وفرمائيل چې پاڅم او ستاسو لارښودنه وکړم، چې تاسو هغه مُلک ونيسئ چې د کوم وعده يې ستاسو پلار نيکۀ سره کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4773, 'Deuteronomy 10:12', 'Deuteronomy', 10, 12, '&nbsp;اوس، اے بنى اِسرائيلو، هغه څۀ واورئ چې مالِک خُدائ ستاسو خُدائ پاک يې ستاسو نه غواړى. د مالِک خُدائ خپل خُدائ پاک نه يرېږئ، د هغۀ پوره تابعدارى کوئ، د هغۀ سره مينه کوئ او د زړۀ د اخلاصه او د خپل ټول روح سره د هغۀ خِدمت کوئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4774, 'Deuteronomy 10:13', 'Deuteronomy', 10, 13, '&nbsp;او د هغۀ ټول قانون منئ. دا زۀ نن ستاسو د فائدې دپاره درکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4775, 'Deuteronomy 10:14', 'Deuteronomy', 10, 14, '&nbsp;ګورئ، دا اوچت آسمانونه د مالِک خُدائ دى، دا زمکه او په دې کښې هر څۀ د هغۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4776, 'Deuteronomy 10:15', 'Deuteronomy', 10, 15, '&nbsp;خو د مالِک خُدائ مينه ستاسو پلار نيکۀ سره دومره زياته وه چې د نورو خلقو په ځائ يې تاسو خوښ کړئ او تر اوسه پورې د هغۀ غوره خلق يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4777, 'Deuteronomy 10:16', 'Deuteronomy', 10, 16, '&nbsp;نو د اوس نه د مالِک خُدائ تابعداره اوسئ او خپل ضد پرېږدئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4778, 'Deuteronomy 10:17', 'Deuteronomy', 10, 17, '&nbsp;مالِک خُدائ ستاسو خُدائ پاک د معبودانو خُدائ پاک او د مالِکانو مالِک خُدائ دے. هغه لوئ او طاقتور دے، د هغۀ نه يره په کار ده. هغه نۀ د چا طرفدارى کوى او نۀ رشوت اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4779, 'Deuteronomy 10:18', 'Deuteronomy', 10, 18, '&nbsp;هغه دا ګورى چې د يتيمانو او کونډو سره ښۀ سلوک کيږى او کۀ نه، هغه د مسافرو سره مينه کوى کوم چې زمونږ خلقو سره اوسيږى او هغوئ له خوراک او جامې ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4780, 'Deuteronomy 10:19', 'Deuteronomy', 10, 19, '&nbsp;نو د مسافرو سره مينه کوئ، ځکه چې په يو وخت کښې تاسو هم د مِصر په مُلک کښې مسافر وئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4781, 'Deuteronomy 10:20', 'Deuteronomy', 10, 20, '&nbsp;مالِک خُدائ د خپل خُدائ پاک نه يرېږئ او صِرف د هغۀ عبادت کوئ. د هغۀ وفادار اوسئ او صِرف د هغۀ په نوم قسم خورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4782, 'Deuteronomy 10:21', 'Deuteronomy', 10, 21, '&nbsp;د هغۀ ثناء وايئ، هغه ستاسو خُدائ پاک دے او تاسو په خپلو سترګو هغه لوئ او عجيبه کارونه ليدلى دى چې ستاسو دپاره يې کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4783, 'Deuteronomy 10:22', 'Deuteronomy', 10, 22, '&nbsp;کله چې ستاسو پلار نيکۀ مِصر ته لاړل، هغوئ صِرف اويا کسان وُو. خو اوس مالِک خُدائ ستاسو خُدائ پاک تاسو د آسمان د ستورو په شان بې‌شمېره کړى يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4784, 'Deuteronomy 11:1', 'Deuteronomy', 11, 1, '&nbsp;مالِک خُدائ خپل خُدائ پاک سره مينه کوئ او د هغۀ ټولې مطالبې، اصُول، قانون او حُکمونه منئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4785, 'Deuteronomy 11:2', 'Deuteronomy', 11, 2, '&nbsp;چې تاسو د مالِک خُدائ په حقله څۀ زده کړى دى نو هغه اوس ياد ساتئ. ستاسو په بچو نه بلکې په تاسو پخپله دا واقعې تېرې شوې. تاسو د مالِک خُدائ لوئى، د هغۀ طاقت، د هغۀ قوت،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4786, 'Deuteronomy 11:3', 'Deuteronomy', 11, 3, '&nbsp;او د هغۀ معجزې وليدلې. تاسو وليدل چې هغۀ د مِصر په بادشاه فِرعون او د هغۀ په ټول مُلک باندې څۀ وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4787, 'Deuteronomy 11:4', 'Deuteronomy', 11, 4, '&nbsp;تاسو وليدل چې مالِک خُدائ د مِصريانو لښکر، سره د هغوئ د آسونو او جنګى ګاډو څنګه تباه کړل او په بحرِقُلزم کښې يې ډُوب کړل کله چې هغوئ تاسو پسې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4788, 'Deuteronomy 11:5', 'Deuteronomy', 11, 5, '&nbsp;تاسو ته پته ده چې مالِک خُدائ ستاسو دې ځائ ته رارسېدو نه مخکښې په بيابان کښې څۀ وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4789, 'Deuteronomy 11:6', 'Deuteronomy', 11, 6, '&nbsp;هغه راياد کړئ چې د روبين قبيلې د اِلياب د زامنو، داتن او ابيرام سره يې څۀ وکړل. د ټولو په مخکښې زمکه وچاوده او هغوئ يې سره د خپلو کورَنو، د خپلو خېمو او د هغوئ د ټولو نوکرانو او ځناورو تېر کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4790, 'Deuteronomy 11:7', 'Deuteronomy', 11, 7, '&nbsp;آو، تاسو هم هغه خلق يئ چې په خپلو سترګو مو هغه ټول کارونه ليدلى دى څۀ چې مالِک خُدائ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4791, 'Deuteronomy 11:8', 'Deuteronomy', 11, 8, '&nbsp;نن چې زۀ کوم قانون درکوم په هغه ټول عمل کوئ، نو تاسو ته به طاقت مِلاو شى چې د سيند نه پورې وځئ او هغه مُلک قبضه کړئ کوم ته چې تاسو وردننه کېدونکى يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4792, 'Deuteronomy 11:9', 'Deuteronomy', 11, 9, '&nbsp;نو تاسو به په هغه مُلک کښې ډېره موده تېره کړئ چې مالِک خُدائ ستاسو پلار نيکۀ او د هغوئ اولاد له يې د ورکولو وعده کړې ده، هغه مُلک چې زرخېزه او آباد دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4793, 'Deuteronomy 11:10', 'Deuteronomy', 11, 10, '&nbsp;کوم مُلک چې تاسو قبضه کوئ هغه مُلک د مِصر په شان نۀ دے، چرته چې تاسو مخکښې اوسېدئ. هلته به چې تاسو تخم کَرلو، نو د پټو اوبو کولو دپاره به تاسو سخته خوارى کوله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4794, 'Deuteronomy 11:11', 'Deuteronomy', 11, 11, '&nbsp;خو چې تاسو کومې زمکې ته ورننوځئ هغه د غرونو، مېدانونو مُلک دے، يو داسې مُلک چې په باران اوبۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4795, 'Deuteronomy 11:12', 'Deuteronomy', 11, 12, '&nbsp;مالِک خُدائ ستاسو خُدائ پاک د دې مُلک خيال ساتى او د کال په هر موسم کښې يې ورباندې نظر وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4796, 'Deuteronomy 11:13', 'Deuteronomy', 11, 13, '&nbsp;نو کۀ تاسو زما په حُکمونو په وفادارۍ سره عمل کوئ کوم چې نن ما درکړى دى، او تاسو د مالِک خُدائ د خپل خُدائ پاک سره مينه کوئ او د زړۀ د اخلاصه د هغۀ خِدمت کوئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4797, 'Deuteronomy 11:14', 'Deuteronomy', 11, 14, '&nbsp;نو بيا به هغه ستاسو په مُلک کښې په صحيح موسم کښې، په خزان او سپرلى کښې بارانونه ووروى، نو تاسو به د زيتُونو تېل، غله او انګور راټولوئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4798, 'Deuteronomy 11:15', 'Deuteronomy', 11, 15, '&nbsp;او د څاروو دپاره به واښۀ درته ملاويږى. او ستا دپاره به خوراک ډېر وى او تاسو به ماړۀ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4799, 'Deuteronomy 11:16', 'Deuteronomy', 11, 16, '&nbsp;پام کوئ، چې خپل زړونه مو دوکه نۀ کړى چې د مالِک خُدائ نه واوړئ او د نورو معبودانو خِدمت او عبادت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4800, 'Deuteronomy 11:17', 'Deuteronomy', 11, 17, '&nbsp;کۀ تاسو داسې وکړل نو مالِک خُدائ به تاسو ته په قهر شى. هغه به د آسمان نه په تاسو باران بند کړى او ستاسو زمکه به اوچه شى او فصلونه به نۀ راشنۀ کوى. بيا به تاسو زر هلته مړۀ شئ، اګر چې هغه زمکه ښۀ ده کومه چې تاسو له درکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');